describe('Column Visibility Toggle in Table List', () => {
  beforeEach(() => {
    cy.visit('/table-list');
  });

  it('should toggle column visibility from settings menu and update table display', () => {
    // Verify initial table state with all columns visible
    cy.get('[data-testid="table-container"]').should('be.visible');
    cy.get('[data-testid="column-name-1"]').should('be.visible');
    cy.get('[data-testid="column-name-2"]').should('be.visible');
    cy.get('[data-testid="column-name-3"]').should('be.visible');

    // Verify settings menu is visible
    cy.get('[data-testid="settings-menu"]').should('be.visible');

    // Click on the settings menu
    cy.get('[data-testid="settings-menu"]').click();

    // Verify column visibility toggle button is visible
    cy.get('[data-testid="toggle-column-btn"]').should('be.visible');

    // Click on the toggle button for column 2
    cy.get('[data-testid="toggle-column-btn"]').click();

    // Verify column 2 is now hidden
    cy.get('[data-testid="column-name-2"]').should('not.be.visible');

    // Verify column 1 and 3 are still visible
    cy.get('[data-testid="column-name-1"]').should('be.visible');
    cy.get('[data-testid="column-name-3"]').should('be.visible');

    // Verify table data is still displayed correctly
    cy.get('[data-testid="table-row-1"]').should('be.visible');
    cy.get('[data-testid="table-row-2"]').should('be.visible');

    // Verify settings menu is still visible
    cy.get('[data-testid="settings-menu"]').should('be.visible');

    // Click on the settings menu again to toggle column 3
    cy.get('[data-testid="settings-menu"]').click();

    // Verify column 3 is now visible again
    cy.get('[data-testid="column-name-3"]').should('be.visible');

    // Verify column 2 remains hidden
    cy.get('[data-testid="column-name-2"]').should('not.be.visible');

    // Verify table data is still displayed correctly
    cy.get('[data-testid="table-row-1"]').should('be.visible');
    cy.get('[data-testid="table-row-2"]').should('be.visible');

    // Verify settings menu is still visible
    cy.get('[data-testid="settings-menu"]').should('be.visible');
  });

  it('should handle edge case where all columns are hidden and cannot be toggled', () => {
    // Verify initial table state with all columns visible
    cy.get('[data-testid="table-container"]').should('be.visible');
    cy.get('[data-testid="column-name-1"]').should('be.visible');
    cy.get('[data-testid="column-name-2"]').should('be.visible');
    cy.get('[data-testid="column-name-3"]').should('be.visible');

    // Click on the settings menu
    cy.get('[data-testid="settings-menu"]').click();

    // Verify column visibility toggle button is visible
    cy.get('[data-testid="toggle-column-btn"]').should('be.visible');

    // Click on the toggle button for column 1
    cy.get('[data-testid="toggle-column-btn"]').click();

    // Verify column 1 is now hidden
    cy.get('[data-testid="column-name-1"]').should('not.be.visible');

    // Verify column 2 and 3 are still visible
    cy.get('[data-testid="column-name-2"]').should('be.visible');
    cy.get('[data-testid="column-name-3"]').should('be.visible');

    // Verify table data is still displayed correctly
    cy.get('[data-testid="table-row-1"]').should('be.visible');
    cy.get('[data-testid="table-row-2"]').should('be.visible');

    // Click on the settings menu again to try to toggle column 2
    cy.get('[data-testid="settings-menu"]').click();

    // Verify column 2 is still visible (cannot be toggled)
    cy.get('[data-testid="column-name-2"]').should('be.visible');

    // Verify column 3 is still visible
    cy.get('[data-testid="column-name-3"]').should('be.visible');

    // Verify settings menu is still visible
    cy.get('[data-testid="settings-menu"]').should('be.visible');

    // Verify no error message is displayed when all columns are hidden
    cy.get('[data-testid="error-message"]').should('not.exist');
  });
});
